contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory tos, uint[] memory v, uint vlen) public payable {
        require(vlen <= v.length);
        uint[] memory vals = new uint[](vlen);
        for (uint i = 0; i < vlen; i++) {
            vals[i] = v[i];
        }

        bool reverted;
        try c.transfer(tos, vals) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool[] memory outcomes = new bool[](vlen);
        if (!reverted && tos.length > 0) {
            require(tos.length == vals.length);
            for (uint i = 0; i < tos.length; i++) {
                outcomes[i] = true;
            }
        }

        uint balanceDelta = address(this).balance;
        assert((tos.length == 0 || reverted || !reverted) && balanceDelta == address(this).balance);
    }

    receive() external payable {}
}

